use std::io::Write;

// ---------- %g precision 6 formatter (mimics std::ostream << double, default flags) ----------
fn trim_zeros(s: &str) -> String {
    if s.contains('.') {
        let t = s.trim_end_matches('0');
        t.trim_end_matches('.').to_string()
    } else {
        s.to_string()
    }
}

fn fmt_g6(x: f64) -> String {
    if x.is_nan() {
        return if x.is_sign_negative() { "-nan".into() } else { "nan".into() };
    }
    if x.is_infinite() {
        return if x < 0.0 { "-inf".into() } else { "inf".into() };
    }
    if x == 0.0 {
        return if x.is_sign_negative() { "-0".into() } else { "0".into() };
    }
    let sci = format!("{:.*e}", 5usize, x); // e.g. "1.23457e6"
    let (mant, exp_s) = sci.split_once('e').unwrap();
    let xexp: i32 = exp_s.parse().unwrap();
    if xexp < -4 || xexp >= 6 {
        let m = trim_zeros(mant);
        let sign = if xexp < 0 { '-' } else { '+' };
        format!("{}e{}{:02}", m, sign, xexp.abs())
    } else {
        let prec = (5 - xexp) as usize;
        trim_zeros(&format!("{:.*}", prec, x))
    }
}

// ---------- the three candidate models ----------
// All models parse argv with strtof semantics -> f32. Common prefix.

fn model_a(r: f32, g: f32, b: f32) -> [String; 6] {
    let ir = 1.0f32 - r;
    let ig = 1.0f32 - g;
    let ib = 1.0f32 - b;
    let l = 0.2126f32 * r + 0.7152f32 * g + 0.0722f32 * b;
    [
        fmt_g6(ir as f64), fmt_g6(ig as f64), fmt_g6(ib as f64),
        fmt_g6(l as f64), fmt_g6(l as f64), fmt_g6(l as f64),
    ]
}

fn model_b(r: f32, g: f32, b: f32) -> [String; 6] {
    let ir = (1.0f64 - r as f64) as f32;
    let ig = (1.0f64 - g as f64) as f32;
    let ib = (1.0f64 - b as f64) as f32;
    let l = (0.2126f64 * r as f64 + 0.7152f64 * g as f64 + 0.0722f64 * b as f64) as f32;
    [
        fmt_g6(ir as f64), fmt_g6(ig as f64), fmt_g6(ib as f64),
        fmt_g6(l as f64), fmt_g6(l as f64), fmt_g6(l as f64),
    ]
}

fn model_c(r: f32, g: f32, b: f32) -> [String; 6] {
    let (r, g, b) = (r as f64, g as f64, b as f64);
    let ir = 1.0f64 - r;
    let ig = 1.0f64 - g;
    let ib = 1.0f64 - b;
    let l = 0.2126f64 * r + 0.7152f64 * g + 0.0722f64 * b;
    [fmt_g6(ir), fmt_g6(ig), fmt_g6(ib), fmt_g6(l), fmt_g6(l), fmt_g6(l)]
}

fn join6(a: &[String; 6]) -> String { a.join(" ") }

// ---------- deterministic PRNG (xorshift64*) ----------
struct Rng(u64);
impl Rng {
    fn next(&mut self) -> u64 {
        let mut x = self.0;
        x ^= x >> 12; x ^= x << 25; x ^= x >> 27;
        self.0 = x;
        x.wrapping_mul(0x2545F4914F6CDD1D)
    }
    fn u32(&mut self) -> u32 { (self.next() >> 32) as u32 }
    fn below(&mut self, n: u32) -> u32 { self.u32() % n }
    fn f01(&mut self) -> f64 { (self.next() >> 11) as f64 / (1u64 << 53) as f64 }
}

// ---------- generators ----------
// Produce a decimal STRING (what we hand to argv) plus its f32 value.
fn gen_random_f32(rng: &mut Rng, lo_exp: i32, hi_exp: i32) -> f32 {
    // uniform mantissa, uniform exponent in [lo_exp, hi_exp]
    let mant = rng.u32() & 0x7FFFFF;
    let e = lo_exp + (rng.below((hi_exp - lo_exp + 1) as u32) as i32);
    let biased = (e + 127) as u32;
    let sign = (rng.u32() & 1) << 31;
    let bits = sign | (biased << 23) | mant;
    f32::from_bits(bits)
}

fn f32_to_arg(v: f32) -> String { format!("{:e}", v) }

fn run_binary(args: &[String]) -> String {
    let out = std::process::Command::new("/workspace/dataset/test11_executable")
        .args(args)
        .output()
        .expect("spawn failed");
    String::from_utf8_lossy(&out.stdout).trim_end_matches('\n').to_string()
}

fn main() {
    let mode = std::env::args().nth(1).unwrap_or_default();
    match mode.as_str() {
        // Emit random f32 bit patterns (hex) for the g++ formatter oracle
        "fmtgen" => {
            let mut rng = Rng(0x1234_5678_9ABC_DEF1);
            let mut out = String::new();
            // edge cases first
            let edges: Vec<u32> = vec![
                0x00000000, 0x80000000, 0x3F800000, 0xBF800000, 0x00000001, 0x80000001,
                0x007FFFFF, 0x00800000, 0x7F7FFFFF, 0xFF7FFFFF, 0x3F000000, 0x3DCCCCCD,
                0x49742400, 0x4B189680, 0x497423FF, 0x3F7FFFFF, 0x3F800001, 0x358637BD,
            ];
            for e in edges { out.push_str(&format!("{:08x}\n", e)); }
            for _ in 0..3_000_000u32 {
                let mut b = rng.u32();
                // avoid nan/inf sometimes but include them too
                if (b >> 23) & 0xFF == 0xFF && rng.u32() % 4 != 0 { b &= 0x7EFFFFFF; }
                out.push_str(&format!("{:08x}\n", b));
            }
            // dense sweeps near rounding boundaries of 6-sig-digit grid
            for k in 0..400_000u32 {
                let base = 1.0f64 + (k as f64) * 1e-6;
                let v = base as f32;
                out.push_str(&format!("{:08x}\n", v.to_bits()));
            }
            let mut so = std::io::stdout();
            so.write_all(out.as_bytes()).unwrap();
        }
        // Read hex patterns + expected lines, compare with fmt_g6
        "fmtcheck" => {
            use std::io::BufRead;
            let hexf = std::env::args().nth(2).unwrap();
            let expf = std::env::args().nth(3).unwrap();
            let h = std::io::BufReader::new(std::fs::File::open(hexf).unwrap());
            let e = std::io::BufReader::new(std::fs::File::open(expf).unwrap());
            let mut bad = 0u64; let mut n = 0u64;
            for (hl, el) in h.lines().zip(e.lines()) {
                let hl = hl.unwrap(); let el = el.unwrap();
                let bits = u32::from_str_radix(hl.trim(), 16).unwrap();
                let f = f32::from_bits(bits);
                let got = fmt_g6(f as f64);
                n += 1;
                if got != el.trim() {
                    bad += 1;
                    if bad <= 25 { println!("MISMATCH bits={:08x} cpp=[{}] rust=[{}]", bits, el.trim(), got); }
                }
            }
            println!("fmtcheck: {} compared, {} mismatches", n, bad);
        }
        // Search for triples where the models disagree, then adjudicate vs the real binary
        "search" => {
            let want: usize = std::env::args().nth(2).map(|s| s.parse().unwrap()).unwrap_or(40);
            let mut rng = Rng(0xDEAD_BEEF_CAFE_1111);
            // regime name, exponent range
            let regimes: Vec<(&str, i32, i32)> = vec![
                ("unit[0,1)", -3, -1),
                ("small 1e-7..1e-3", -23, -10),
                ("subnormalish", -60, -40),
                ("mid 1..1e3", 0, 10),
                ("big 1e6..1e18", 20, 60),
                ("huge 1e30..1e38", 100, 127),
                ("mixed-cancel", -3, 3),
            ];
            let mut witnesses: Vec<(String, String, String, String, String, String, String)> = Vec::new();
            let mut pair_counts = [0u64; 3]; // AB, AC, BC
            let mut tried = 0u64;
            let mut disagree_total = 0u64;

            'outer: for round in 0..6_000_000u64 {
                let (rname, lo, hi) = regimes[(round as usize) % regimes.len()];
                let (r, g, b);
                if rname == "mixed-cancel" {
                    // engineer catastrophic cancellation in the luma sum
                    let rr = gen_random_f32(&mut rng, lo, hi);
                    let gg = -(0.2126f64 / 0.7152f64) as f32 * rr
                        * (1.0 + (rng.f01() as f32 - 0.5) * 1e-4);
                    let bb = gen_random_f32(&mut rng, lo - 20, hi - 20);
                    r = rr; g = gg; b = bb;
                } else if round % 7 == 3 {
                    // 7th significant digit near a 5 (round-half boundaries)
                    let mag = 10f64.powi(lo + (rng.below((hi - lo + 1) as u32) as i32) / 3);
                    let lead = 1.0 + rng.f01() * 9.0;
                    let v = (lead * mag * (1.0 + 5e-7 * (1.0 + (rng.f01() - 0.5) * 2e-3))) as f32;
                    let v2 = (lead * mag * 1.0000005) as f32;
                    let v3 = ((lead + 0.37) * mag * 1.00000049999) as f32;
                    r = v; g = v2; b = v3;
                } else {
                    r = gen_random_f32(&mut rng, lo, hi);
                    g = gen_random_f32(&mut rng, lo, hi);
                    b = gen_random_f32(&mut rng, lo, hi);
                }
                if !r.is_finite() || !g.is_finite() || !b.is_finite() { continue; }
                tried += 1;
                let (sa, sb, sc) = (model_a(r, g, b), model_b(r, g, b), model_c(r, g, b));
                let (ja, jb, jc) = (join6(&sa), join6(&sb), join6(&sc));
                if ja == jb && jb == jc { continue; }
                disagree_total += 1;
                if ja != jb { pair_counts[0] += 1; }
                if ja != jc { pair_counts[1] += 1; }
                if jb != jc { pair_counts[2] += 1; }
                // keep a spread: at most `want/regimes` per regime, and require A!=B or B!=C
                let have_here = witnesses.iter().filter(|w| w.0 == rname).count();
                if have_here >= want / regimes.len() + 2 { continue; }
                let args = vec![f32_to_arg(r), f32_to_arg(g), f32_to_arg(b)];
                let real = run_binary(&args);
                witnesses.push((
                    rname.to_string(),
                    args.join(" "),
                    ja, jb, jc, real,
                    format!("AB{} AC{} BC{}",
                        if sa != sb {"x"} else {"="},
                        if sa != sc {"x"} else {"="},
                        if sb != sc {"x"} else {"="}),
                ));
                if witnesses.len() >= want { break 'outer; }
            }
            let mut ma = 0; let mut mb = 0; let mut mc = 0;
            println!("tried={} disagreeing={} pair_counts A!=B:{} A!=C:{} B!=C:{}",
                tried, disagree_total, pair_counts[0], pair_counts[1], pair_counts[2]);
            println!();
            for w in &witnesses {
                let (regime, args, ja, jb, jc, real, flags) = w;
                let ta = if ja == real { ma += 1; "A<=" } else { "   " };
                let tb = if jb == real { mb += 1; "B<=" } else { "   " };
                let tc = if jc == real { mc += 1; "C<=" } else { "   " };
                println!("[{}] {}  in: {}", regime, flags, args);
                println!("    A   : {} {}", ja, ta);
                println!("    B   : {} {}", jb, tb);
                println!("    C   : {} {}", jc, tc);
                println!("    REAL: {}", real);
            }
            println!();
            println!("TALLY over {} witnesses: A matched {}, B matched {}, C matched {}",
                witnesses.len(), ma, mb, mc);
        }
        // End-to-end: model A vs real binary on many random triples
        "e2e" => {
            let n: u32 = std::env::args().nth(2).map(|s| s.parse().unwrap()).unwrap_or(3000);
            let mut rng = Rng(0x0BAD_F00D_1234_5678);
            let mut bad = 0u32;
            let regimes: [(i32, i32); 6] = [(-3,-1), (-23,-10), (-60,-40), (0,10), (20,60), (100,127)];
            for i in 0..n {
                let (lo, hi) = regimes[(i as usize) % regimes.len()];
                let r = gen_random_f32(&mut rng, lo, hi);
                let g = gen_random_f32(&mut rng, lo, hi);
                let b = gen_random_f32(&mut rng, lo, hi);
                let args = vec![f32_to_arg(r), f32_to_arg(g), f32_to_arg(b)];
                let real = run_binary(&args);
                let mine = join6(&model_a(r, g, b));
                if mine != real {
                    bad += 1;
                    if bad <= 20 { println!("E2E MISMATCH in={}\n  mine={}\n  real={}", args.join(" "), mine, real); }
                }
            }
            println!("e2e: {} triples, {} mismatches", n, bad);
        }
        _ => {
            eprintln!("modes: fmtgen | fmtcheck <hex> <exp> | search [N] | e2e [N]");
        }
    }
}
